INSERT INTO `routes` VALUES (5,'Pradera Directo','Sale de Pradera Dorada pasando por UPSIN, El Conchi y Av. Gabriel Leyva hasta el Centro y Embarcadero Isla de la Piedra.','#ff0400',1,13.0,12,3.5),(6,'Lomas del Ébano Central','Baja de Lomas del Ébano y El Conchi por Av. Insurgentes, pasa por el IMSS, Central Camionera, Malecón y llega al Centro.','#1e88e5',1,13.0,20,3.5),(7,'Milenio Cerritos-Pradera','Conecta Pradera Dorada, UAS e ITMAZ con Plaza Acaya, Tecmilenio, La Marina y las playas de Cerritos.','#fb8c00',1,15.0,18,3.5),(8,'Sabalo Centro ','Recorre la zona hotelera desde Cerritos y Zona Dorada por todo el Malecón hasta Olas Altas, Playa Sur, Centro y Gran Acuario.','#4dff00',1,16.0,12,3.5),(9,'Villa Galaxia-Mañanitas','Pasa por Villa Galaxia, UPSIN, IMSS, Central Camionera, Malecón, Mercado Pino Suárez y Olas Altas.','#d81b60',1,15.0,17,3.5),(10,'San Joaquin Sabalo','Va de Pradera y UPSIN por Plaza Acaya, Zona Dorada y Av. Rafael Buelna (Valentino\'s, Sharp, Ley del Mar) hasta El Conchi.','#00acc1',1,15.0,13,3.5),(11,'Jabalies','Cruza desde Pradera y UPSIN por ISSSTE, IMSS, Central Camionera, Malecón, Olas Altas y el Mercado Pino Suárez.','#3949ab',1,13.0,14,3.5),(12,'Urias Sabalo','Sube desde Urías (ITMAZ, CETMAR, Conalep I) por Carretera Internacional y Av. Rafael Buelna directo hacia Zona Dorada y Valentino\'s.','#e100ff',1,15.0,15,3.5),(13,'Sirena','Conecta Urías, Conalep I y El Conchi con el IMSS, Central Camionera, Malecón, Centro y Terminal de Cruceros.','#2e7d32',1,15.0,14,3.5),(14,'Zapata Juarez','Sale de Pradera Dorada y Santa Rosa pasando por Col. Benito Juárez, Hospital Margarita Maza, Cruz Roja y Mercado Pino Suárez.','#0277bd',1,15.0,17,3.5),(16,'Centro Colonias','Conecta Urías (Conalep I) y Col. Benito Juárez con Av. Ejército Mexicano (IMSS, Central Camionera), Malecón, Mercado Pino Suárez, Catedral e ITMAZ.','#d671bb',1,13.0,22,3.5),(17,'Prados Del Sol','Sale de Prados del Sol, Centro de Convenciones y Galerías pasando por Carretera Internacion